import numpy as np
def softmax(z):
    z=np.asarray(z,dtype=float)
    e=np.exp(z-z.max(axis=1,keepdims=True))
    return e/e.sum(axis=1,keepdims=True)

import numpy as np
def accuracy(scores,labels):
    return float((np.asarray(scores).argmax(axis=1)==np.asarray(labels)).mean())

import numpy as np
def nll(p,y):
    p=np.asarray(p,dtype=float)
    y=np.asarray(y,dtype=int)
    selected=p[np.arange(len(y)),y]
    return float(-np.log(np.clip(selected,1e-12,1)).mean())

import numpy as np
def ece(confidence,correct,bins=2):
    c,r=np.asarray(confidence),np.asarray(correct)
    total=0.0
    for i in range(bins):
        lower,upper=i/bins,(i+1)/bins
        mask=(c>=lower)&((c<upper) if i<bins-1 else (c<=upper))
        if mask.any():
            total+=mask.mean()*abs(c[mask].mean()-r[mask].mean())
    return float(total)

